// Sniperモード自動最適化 2026-08-24 09:40 / 3688件データ
// Sniper: 37件 勝率75.7% 平均3.7%
// 【Sniper条件（全6条件通過で採択）】
//   ① ATR% < 3.0%
//   ② 直近20日高値更新
//   ③ RSI 50〜70
//   ④ 一目: 転換線 > 基準線
//   ⑤ RCI(9) ≤ -50（短期売られすぎ）
//   ⑥ ギャップアップ（始値>前終値）

function calculateScoreSniper(ind) {
  if (!ind) return null;
  const filters = [];
  let score = 0;

  // ① ATR% < 3.0%
  if (ind.atrPct < 3.0) {
    score++;
    filters.push(`①ATR(${ind.atrPct}%)`);
  }

  // ② 直近20日高値更新
  if (ind.hiBrk20) {
    score++;
    filters.push(`②高値更新`);
  }

  // ③ RSI 50〜70
  if (!isNaN(ind.rsi14) && ind.rsi14 >= 50 && ind.rsi14 < 70) {
    score++;
    filters.push(`③RSI(${ind.rsi14.toFixed(0)})`);
  }

  // ④ 一目: 転換線 > 基準線
  if (ind.ichTenkan !== null && ind.ichKijun !== null && ind.ichTenkan > ind.ichKijun) {
    score++;
    filters.push(`④一目TK`);
  }

  // ⑤ RCI(9) ≤ -50（短期売られすぎ）
  if (ind.rci9 !== null && ind.rci9 <= -50) {
    score++;
    filters.push(`⑤RCI9(${ind.rci9 !== null ? ind.rci9.toFixed(0) : 'N/A'})`);
  }

  // ⑥ ギャップアップ（始値>前終値）
  if (ind.gapUp) {
    score++;
    filters.push(`⑥GAP-UP`);
  }

  return { score, filters };
}
